+<script>
+const canvas = document.getElementById('hexBg');
+const ctx = canvas.getContext('2d');
+let W, H, t = 0;
+function resize() { W = canvas.width = innerWidth; H = canvas.height = innerHeight; }
+resize(); addEventListener('resize', resize);
+function drawHex() {
+  ctx.clearRect(0, 0, W, H);
+  const cell = 24;
+  const hexW = cell * Math.sqrt(3);
+  const hexH = cell * 1.5;
+  ctx.save();
+  ctx.translate(W / 2, H / 2); ctx.rotate(t * 0.00008); ctx.translate(-W / 2, -H / 2);
+  for (let y = -hexH; y < H + hexH; y += hexH) {
+    for (let x = -hexW; x < W + hexW; x += hexW) {
+      const off = (Math.round(y / hexH) % 2) * (hexW / 2);
+      const cx = x + off, cy = y;
+      const dx = (cx - W / 2) / W, dy = (cy - H / 2) / H;
+      const d = Math.sqrt(dx * dx + dy * dy);
+      const fade = Math.max(0, 1 - Math.pow(d * 1.5, 2));
+      ctx.strokeStyle = `rgba(255,255,255,${0.06 * fade})`;
+      ctx.lineWidth = 0.6;
+      ctx.beginPath();
+      for (let i = 0; i < 6; i++) {
+        const ang = Math.PI / 3 * i + Math.PI / 6;
+        const px = cx + cell * Math.cos(ang);
+        const py = cy + cell * Math.sin(ang);
+        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
+      }
+      ctx.closePath(); ctx.stroke();
+    }
+  }
+  ctx.restore();
+  t++;
+  requestAnimationFrame(drawHex);
+}
+drawHex();
+</script>
